#!/usr/bin/env python3
"""Poll the 4 Devin sessions until each returns structured_output (or dies /
times out), then synthesize a legit verdict per target (browse + research)."""

from __future__ import annotations

import json
import time
import urllib.error
import urllib.request
from pathlib import Path

HERE = Path(__file__).resolve().parent
IN = HERE / "devin_sessions.json"
OUT = HERE / "devin_results.json"
REPO = Path("/Users/lukasz/Code/Munich Hackathon/munich-hackathon-tum")
BASE = "https://api.devin.ai/v3"
DEADLINE_S = 1200
POLL_S = 20
DEAD = {"exit", "error", "suspended"}


def read_key() -> str:
    for line in (REPO / ".env").read_text().splitlines():
        line = line.strip()
        if line.startswith("DEVIN_API_KEY="):
            val = line.split("=", 1)[1].strip()
            if len(val) >= 2 and val[0] in "\"'" and val[-1] == val[0]:
                val = val[1:-1]
            return val
    raise SystemExit("no key")


def get(path: str, key: str) -> dict:
    req = urllib.request.Request(f"{BASE}{path}", method="GET")
    req.add_header("Authorization", f"Bearer {key}")
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return json.loads(r.read() or "{}")
    except urllib.error.HTTPError as e:
        return {"_http_error": e.code, "_body": e.read().decode()[:200]}


def as_obj(raw) -> dict | None:
    if raw is None:
        return None
    if isinstance(raw, dict):
        return raw
    if isinstance(raw, str):
        try:
            v = json.loads(raw.strip().strip("`"))
            return v if isinstance(v, dict) else None
        except Exception:
            return None
    return None


def main() -> int:
    key = read_key()
    doc = json.loads(IN.read_text())
    org = doc["org_id"]
    sessions = doc["sessions"]
    results: dict[str, dict] = {}
    deadline = time.monotonic() + DEADLINE_S

    while True:
        pending = [s for s in sessions if s["label"] not in results]
        if not pending:
            break
        for s in pending:
            d = get(f"/organizations/{org}/sessions/{s['session_id']}", key)
            out = as_obj(d.get("structured_output"))
            status = d.get("status")
            if out is not None:
                results[s["label"]] = {
                    "out": out, "acus": d.get("acus_consumed"), "status": status,
                }
                print(f"[done] {s['label']:22} verdict={out.get('verdict')} "
                      f"score={out.get('legit_score')} acus={d.get('acus_consumed')}")
            elif status in DEAD:
                results[s["label"]] = {"out": None, "status": status, "dead": True}
                print(f"[dead] {s['label']:22} status={status}")
        if len([s for s in sessions if s['label'] in results]) == len(sessions):
            break
        if time.monotonic() > deadline:
            for s in sessions:
                results.setdefault(s["label"], {"out": None, "status": "TIMEOUT"})
            print("[timeout] deadline hit")
            break
        left = int(deadline - time.monotonic())
        print(f"... {len(results)}/{len(sessions)} done, {left}s left")
        time.sleep(POLL_S)

    # synthesize per target
    targets: dict[str, dict] = {}
    for s in sessions:
        targets.setdefault(s["target"], {"url": s["url"]})
    synthesis = {}
    for target, meta in targets.items():
        b = results.get(f"{target}:browse", {}).get("out")
        r = results.get(f"{target}:research", {}).get("out")
        scores = [x["legit_score"] for x in (b, r) if x and isinstance(x.get("legit_score"), (int, float))]
        avg = sum(scores) / len(scores) if scores else None
        verdict = ("legit" if avg is not None and avg >= 0.65
                   else "suspicious" if avg is not None and avg >= 0.35
                   else "malicious" if avg is not None else "unknown")
        synthesis[target] = {
            "url": meta["url"], "combined_score": avg, "combined_verdict": verdict,
            "browse": b, "research": r,
        }

    OUT.write_text(json.dumps({"results": results, "synthesis": synthesis}, indent=2))

    print("\n" + "=" * 72)
    print("SYNTHESIS — site legitimacy (Devin, browse + research)")
    print("=" * 72)
    for target, s in synthesis.items():
        print(f"\n### {target}  ({s['url']})")
        print(f"  COMBINED: {s['combined_verdict'].upper()}  score={s['combined_score']}")
        for mode, o in (("browse", s["browse"]), ("research", s["research"])):
            if not o:
                print(f"  [{mode}] (no output)")
                continue
            print(f"  [{mode}] {o.get('verdict')} score={o.get('legit_score')} "
                  f"brand={o.get('impersonated_brand','-')}")
            for sig in (o.get("top_signals") or [])[:4]:
                print(f"      - {sig}")
    print(f"\nfull results -> {OUT}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

