#!/usr/bin/env python3
"""Live two-agent link scan on a random URL via stdlib urllib (system python
resolves DNS here). Same prompts/schema/synthesis as app/link_agent_devin.py."""

from __future__ import annotations

import json
import time
import urllib.error
import urllib.request
from pathlib import Path

REPO = Path("/Users/lukasz/Code/Munich Hackathon/munich-hackathon-tum")
BASE = "https://api.devin.ai/v3"
URL = "http://spectrum-webmail-loginzs.framer.website/"  # untested real phishing (Spectrum)
MAX_ACU = 5

SCHEMA = {
    "type": "object",
    "properties": {
        "verdict": {"type": "string"},
        "legit_score": {"type": "number"},
        "impersonated_brand": {"type": "string"},
        "top_signals": {"type": "array", "items": {"type": "string"}},
        "reasoning": {"type": "string"},
    },
    "required": ["verdict", "legit_score", "reasoning"],
}
BROWSE = (
    "You are a defensive web-safety analyst in a sandboxed VM (safe to open risky pages). "
    f"Open and navigate this URL: {URL}. Click through home/login/about/contact/forms. Decide "
    "ONLY from what you observe whether it is the legitimate first-party site for its apparent "
    "brand or a phishing/impersonation clone (where forms submit, TLS, domain vs real brand, "
    "content depth, credential/seed prompts). Observation only. Return the structured verdict; "
    "legit_score 1.0=legit, 0.0=malicious."
)
RESEARCH = (
    "You are a defensive web-safety analyst. WITHOUT loading it in a browser, research this URL's "
    f"reputation via web search/OSINT: {URL}. Domain age/WHOIS, official-domain vs lookalike, "
    "blocklists (PhishTank/OpenPhish/URLhaus/Safe Browsing), throwaway host, impersonated brand. "
    "Return the structured verdict; legit_score 1.0=legit, 0.0=malicious."
)


def key() -> str:
    for ln in (REPO / ".env").read_text().splitlines():
        ln = ln.strip()
        if ln.startswith("DEVIN_API_KEY="):
            v = ln.split("=", 1)[1].strip()
            return v[1:-1] if v[:1] in "\"'" and v[-1:] == v[:1] else v
    raise SystemExit("no key")


K = key()


def api(method: str, path: str, body: dict | None = None) -> dict:
    for attempt in range(5):
        data = json.dumps(body).encode() if body is not None else None
        req = urllib.request.Request(f"{BASE}{path}", data=data, method=method)
        req.add_header("Authorization", f"Bearer {K}")
        req.add_header("Content-Type", "application/json")
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return json.loads(r.read() or "{}")
        except urllib.error.HTTPError as e:
            raise SystemExit(f"HTTP {e.code} {method} {path}: {e.read().decode()[:300]}")
        except urllib.error.URLError:
            if attempt == 4:
                raise
            time.sleep(5)
    return {}


def looks_final(out) -> bool:
    return isinstance(out, dict) and "progress" not in str(out.get("verdict", "")).lower()


def main() -> None:
    org = api("GET", "/self")["org_id"]
    print(f"auth OK; scanning random link: {URL}")
    ids = {}
    for label, prompt in (("browse", BROWSE), ("research", RESEARCH)):
        r = api(
            "POST",
            f"/organizations/{org}/sessions",
            {
                "prompt": prompt,
                "resumable": False,
                "max_acu_limit": MAX_ACU,
                "structured_output_required": True,
                "structured_output_schema": SCHEMA,
            },
        )
        ids[label] = r["session_id"]
        print(f"  {label} session: {r.get('url')}")

    out: dict[str, dict | None] = {}
    deadline = time.monotonic() + 900
    while len(out) < 2:
        for label, sid in ids.items():
            if label in out:
                continue
            s = api("GET", f"/organizations/{org}/sessions/{sid}")
            so = s.get("structured_output")
            if s.get("structured_output") is not None and looks_final(so):
                out[label] = so
                print(f"  [done] {label}: {so.get('verdict')} ({so.get('legit_score')})")
            elif s.get("status") in {"exit", "error", "suspended"}:
                out[label] = None
                print(f"  [dead] {label}")
        if len(out) == 2 or time.monotonic() > deadline:
            break
        time.sleep(15)

    scores = [float(o["legit_score"]) for o in out.values() if o and "legit_score" in o]
    avg = sum(scores) / len(scores) if scores else 0.5
    verdict = "legit" if avg >= 0.65 else "suspicious" if avg >= 0.35 else "malicious"
    print("\n=== COMBINED VERDICT ===")
    print(f"url          : {URL}")
    print(f"combined     : {verdict.upper()}  score={round(avg, 3)}")
    for label, o in out.items():
        if not o:
            print(f"[{label}] (no output)")
            continue
        print(f"[{label}] {o.get('verdict')} score={o.get('legit_score')} brand={o.get('impersonated_brand', '-')}")
        for s in (o.get("top_signals") or [])[:4]:
            print(f"    - {s}")

    for sid in ids.values():
        try:
            api("DELETE", f"/organizations/{org}/sessions/{sid}")
        except Exception:
            pass
    print("\nsessions terminated (no idle billing)")


if __name__ == "__main__":
    main()

